"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.13527",title:"S-Space: Exploring Spatial Workspace in Multimodal Language Models",up:265,href:"https://arxiv.org/abs/2610.13527",abstract:"Multimodal language models (MLLMs) exhibit promising spatial reasoning capabilities, yet the internal mechanisms supporting them remain poorly understood. We uncover S-Space, a linear representation subspace in which object-token representations encode continuous coordinates along horizontal, vertical, and distance axes. Although we identify these axes by differentiating spatial-answer scores with respect to object-token activations, S-Space is intrinsic rather than induced by specific data or prompts, remaining readable under non-spatial questions. We show that S-Space functions as an interna",pdfUrl:"https://arxiv.org/pdf/2610.13527",primaryCategory:"cs.CV",published:"2026-10-09T12:48:41Z"},{id:"2610.12611",title:"SoftwareGym: Scaling Computer-Use Agent Training with Diverse Synthesized Software Environments",up:85,href:"https://arxiv.org/abs/2610.12611",abstract:"Computer-use agents (CUAs) are rapidly improving, yet synthesizing diverse and reliable software environments at scale remains challenging. Native application environments require substantial construction and integration effort, which limits application coverage and increases the risk of application-specific overfitting. Browser-hosted environments provide limited interaction depth and workflow complexity. These limitations motivate SoftwareGym, an automated pipeline for synthesizing GUI software environments with diverse interfaces, executable functionality, and runtime-verified behavior. It ",pdfUrl:"https://arxiv.org/pdf/2610.12611",primaryCategory:"cs.MA",published:"2026-10-08T00:00:00Z"},{id:"2609.39601",title:"GroundingPI: A Grounding Foundation Model towards Physical Intelligence with Visual Primitives",up:82,href:"https://arxiv.org/abs/2609.39601",abstract:"Precise grounding matters. It specifies which object is the target and where that object is, even in clutter and for tiny objects, and it has to be fast enough for closed-loop control. Yet vision-language-action (VLA) and world-action models (WAMs) take perception from general-purpose vision-language and video-generation backbones, which still fail in these settings. We introduce GroundingPI, a 4B grounding foundation model that generates points and boxes as quantized coordinates in a shared vocabulary. Training combines multimodal and spatial pretraining, supervised fine-tuning, and reinforce",pdfUrl:"https://arxiv.org/pdf/2609.39601",primaryCategory:"cs.CV",published:"2026-09-30T00:00:00Z"},{id:"2610.13166",title:"Scaling Agentic Data for Long-Horizon Terminal Intelligence",up:70,href:"https://arxiv.org/abs/2610.13166",abstract:"Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synth",pdfUrl:"https://arxiv.org/pdf/2610.13166",primaryCategory:"cs.CL",published:"2026-10-09T00:00:00Z"},{id:"2610.12341",title:"Can AI Agents Learn Their Way to the Top? Evaluating Heuristic Learning in a Long-Running Game Agent Competition",up:43,href:"https://arxiv.org/abs/2610.12341",abstract:"Adversarial games have driven advances from heuristic search to reinforcement learning, yet learning and adapting strategies from limited samples remain challenging. AI agents offer an alternative by turning game experience into revisions of executable policies. Building on heuristic learning (HL), we formalize Adversarial Heuristic Learning (AHL), a paradigm that uses AI agents as learning engines to refine game policies and supporting software while keeping model weights fixed. We introduce AAArena, a benchmark comprising 12 authentic adversarial games and 1,920 archived human programs, with",pdfUrl:"https://arxiv.org/pdf/2610.12341",primaryCategory:"cs.AI",published:"2026-10-08T00:00:00Z"},{id:"2610.12984",title:"Work2Skill: Capturing Human GUI Experience for Reusable Agent Skill Induction",up:42,href:"https://arxiv.org/abs/2610.12984",abstract:"Computer-use agents can perform increasingly complex GUI tasks, yet unfamiliar software and workflows requiring human domain knowledge remain challenging. Human demonstrations convey procedural knowledge through the same GUI interaction space, but reuse requires interpreting actions in context and separating workflow rules from task-specific details. We thus introduce Work2Skill, a framework that captures human GUI experience for reusable agent skill induction. WorkRecorder provides the framework's infrastructure for collecting this experience, aligning screen recordings, mouse and keyboard ev",pdfUrl:"https://arxiv.org/pdf/2610.12984",primaryCategory:"cs.AI",published:"2026-10-09T00:00:00Z"},{id:"2610.13113",title:"Continually Post-training Small Models via Synthetic Self-distillation",up:41,href:"https://arxiv.org/abs/2610.13113",abstract:"Continual post-training faces a dual challenge of acquisition and retention: models must learn new capabilities while preserving prior knowledge. While Self-Distillation Fine-Tuning (SDFT) mitigates this using self-supervision with in-context demonstrations, it relies on strong in-context learning and instruction-following abilities. Consequently, SDFT fails on smaller models critical for low-latency, on-device use. To enable continual learning at smaller scales, we first identify the root cause of failure. We show that poor acquisition and forgetting correlate linearly with the post-trained m",pdfUrl:"https://arxiv.org/pdf/2610.13113",primaryCategory:"cs.LG",published:"2026-10-09T00:00:00Z"},{id:"2610.13361",title:"AgentSWE: Can Coding Agents Build the Agent You Actually Want?",up:40,href:"https://arxiv.org/abs/2610.13361",abstract:"As the production of software passes into the hands of software itself, coding agents are increasingly commissioned to build agents fitted to their users' own workflows. This delegation carries a quiet assumption, that the delivered agent will faithfully serve the requirement it was built for, rather than merely appear to. No existing benchmark tests that assumption. We introduce AgentSWE, a benchmark for agent software engineering spanning three stages of the agent development lifecycle: Creation of a complete agent from a natural-language requirement, Editing of production agent codebases, a",pdfUrl:"https://arxiv.org/pdf/2610.13361",primaryCategory:"cs.SE",published:"2026-10-09T00:00:00Z"},{id:"2610.11765",title:"Thinking Inertia: LLMs Keep Thinking When Told Not To",up:38,href:"https://arxiv.org/abs/2610.11765",abstract:'Large Language Models (LLMs) increasingly ship with explicit "thinking modes", yet their counterpart, "no-thinking", has received far less attention. We study LLMs\' no-thinking behavior along two axes. a. How to measure no-thinking? Prior work typically defines no-thinking through proxies such as a disabled thinking mode or the absence of long traces. These proxies are unreliable: disabled thinking modes may still emit reasoning, while long traces may contain filler rather than genuine inference. We instead normalize each response into a pre-answer trace and final answer, and evaluate it at th',pdfUrl:"https://arxiv.org/pdf/2610.11765",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.13630",title:"Multi-Stream Attention Residuals",up:30,href:"https://arxiv.org/abs/2610.13630",abstract:"Attention Residuals (AttnRes) enables content-dependent retrieval over network depth, which can be viewed as single-stream softmax attention along the depth axis. Inspired by the success of multi-head attention along the sequence axis, we introduce Multi-Stream Attention Residuals (MSAR), an extension of AttnRes that generalizes this mechanism to multi-head depth attention, yielding substantial performance gains with minimal additional overhead. MSAR draws stream diversity from sequence context through multi-scale causal convolutions, allowing different heads to retrieve historical representat",pdfUrl:"https://arxiv.org/pdf/2610.13630",primaryCategory:"cs.CL",published:"2026-10-09T00:00:00Z"},{id:"2609.33304",title:"Relevance Does Not Imply Applicability: Experience Activation for Personal GUI Agents",up:29,href:"https://arxiv.org/abs/2609.33304",abstract:"Personal Graphical User Interface (GUI) agents rely on interaction history to infer what a user wants from ambiguous instructions and to anticipate recurring routines. Existing approaches retrieve task-relevant history and append it to the policy's context, implicitly assuming that experience relevant to a task remains useful for each decision within it. We find that this help is largely spent at the first decision: retrieved history strongly improves the opening step of an episode, yet provides little sustained benefit over the remaining 90\\% of steps, and offers weak guidance on whether a pr",pdfUrl:"https://arxiv.org/pdf/2609.33304",primaryCategory:"cs.CV",published:"2026-09-27T00:00:00Z"},{id:"2610.12570",title:"Contextual Correction of Parallel Draftsfor Speculative Decoding",up:26,href:"https://arxiv.org/abs/2610.12570",abstract:"Speculative decoding accelerates large language model inference by using a lightweight drafter to propose multiple tokens that are subsequently verified in parallel by the target model. Recent diffusion-based drafters make this paradigm particularly attractive: deep attention-based neural backbones provide strong predictions, while drafting multiple future positions in parallel avoids the sequential cost of autoregressive generation. This parallelism, however, comes at a cost. Tokens within a draft block are predicted without access to the realized identities of preceding draft tokens, removin",pdfUrl:"https://arxiv.org/pdf/2610.12570",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.08966",title:"Humanity's Sixth Sense: Benchmarking Intuitive Visual Reasoning in Multimodal Models",up:19,href:"https://arxiv.org/abs/2610.08966",abstract:"Humans perceive far more in a scene than what is explicitly depicted: a single glance captures past causes and future trajectories; a quick peek determines if a vehicle can fit between two parked cars; a few seconds of video reveals who holds authority in a room; and a fleeting clip highlights subtle abstract patterns like unwritten rules or hidden labels. This capacity reflects a form of humanity's sixth sense: an intuitive reasoning mechanism that recovers implicit information beyond raw sensory perception. Crucially, this rapid, zero-shot visual intuition underpins everyday navigation and s",pdfUrl:"https://arxiv.org/pdf/2610.08966",primaryCategory:"cs.AI",published:"2026-10-08T00:00:00Z"},{id:"2610.11291",title:"When Do We Need On-Policy Distillation? Distilling on Offline Student Rollouts Is Often Better",up:17,href:"https://arxiv.org/abs/2610.11291",abstract:"On-policy distillation (OPD) has become increasingly popular for transferring teacher capabilities to student models. In this work, we ask a critical research question: Is on-policy sampling always beneficial for distilling arbitrary teacher-student pairs? We show that a simple alternative, Semi-OPD, which distills from offline rollouts generated by the initial student, can often outperform OPD in both accuracy and training efficiency. Across 17 teacher-student pairs ranging from 1.5B to 235B parameters, Semi-OPD outperforms OPD in 14 cases, with up to +13.6% accuracy and 11.4x training speedu",pdfUrl:"https://arxiv.org/pdf/2610.11291",primaryCategory:"cs.CL",published:"2026-10-08T05:54:03Z"},{id:"2609.39600",title:"GroundAnything: Reconciling Parallel Decoding with Precise Visual Grounding at Flash Speed",up:16,href:"https://arxiv.org/abs/2609.39600",abstract:"Autoregressive (AR) grounding models serialize spatial predictions, introducing sequential latency and imposing a causal order on output tokens. We view grounding as visual evidence extraction: objects, locations, and spatial relations are jointly constrained by the image and query, yet their dependencies do not imply an intrinsic left-to-right generation order. This distinction makes bidirectional diffusion a natural fit, allowing spatial hypotheses to emerge in parallel and be jointly refined through iterative denoising. We introduce GroundAnything, a 4B-parameter grounding foundation model ",pdfUrl:"https://arxiv.org/pdf/2609.39600",primaryCategory:"cs.CV",published:"2026-09-30T00:00:00Z"},{id:"2610.05014",title:"MetaKernelBench: Measuring GPU Kernel Knowledge Transfer Beyond Code",up:16,href:"https://arxiv.org/abs/2610.05014",abstract:"Recent GPU kernel optimization agents retain what they learn in knowledge bases or as distilled skills. Kernel benchmarks score each attempt's implementation for correctness and speed but leave the reuse value of retained experience unmeasured. We introduce MetaKernelBench, which measures whether experience distilled from an attempt in one kernel domain-specific language (DSL) improves a fresh attempt at the same problem in another. Its 74 problems are fused subgraphs in six families, each posed as a pair of CuTe DSL and TIRx variants that differ only in the DSL. The agent first attempts each ",pdfUrl:"https://arxiv.org/pdf/2610.05014",primaryCategory:"cs.LG",published:"2026-10-04T00:00:00Z"},{id:"2610.13832",title:"SpatialASM: Internalizing Active Mentalization for Spatial Reasoning",up:15,href:"https://arxiv.org/abs/2610.13832",abstract:"When solving complex spatial reasoning tasks, ordinary humans naturally revisit the scenes from task-relevant viewpoints and mentally reconstruct the spatial layouts from those viewpoints. But can Large Vision-Language Models (LVLMs) proactively think in the same way? We term this ability Active Spatial Mentalization (ASM), an intrinsic component of visual intelligence that remains substantially underdeveloped in current LVLMs. To bridge this gap, we introduce SpatialASM, a scalable framework to internalize ASM into LVLMs through training-time spatial simulation. SpatialASM employs an allocent",pdfUrl:"https://arxiv.org/pdf/2610.13832",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"2610.11993",title:"DataVista: Diagnosing Multimodal LLMs on Data Video Understanding",up:13,href:"https://arxiv.org/abs/2610.11993",abstract:"Data video is a media form that integrates data visualization with video narrative, widely adopted in news reporting and business analysis. Compared with general video understanding, data video understanding places greater emphasis on accurately reading data from animated charts, integrating evidence across charts and time, and understanding how narrative organization and visual design communicate information. Yet existing benchmarks target either general videos or static charts, and data video understanding has not been systematically evaluated. We present DataVista, the first benchmark for d",pdfUrl:"https://arxiv.org/pdf/2610.11993",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.12939",title:"Surfing the Activation Wave: Analyzing the Information and Geometry of LLM Hidden States for Speculative Decoding",up:13,href:"https://arxiv.org/abs/2610.12939",abstract:"Decoder hidden states from different layers of large language models (LLMs) often encode complementary information. However, existing speculative decoding methods typically rely on a small set of target-model layers chosen using fixed, position-based heuristics. Selecting an optimal subset of layers is inherently a combinatorial problem, making exhaustive evaluation infeasible even for moderately deep models. In this work, we present a principled framework for multi-layer hidden-state selection for speculative decoding based on two complementary criteria: informativeness, measured through matr",pdfUrl:"https://arxiv.org/pdf/2610.12939",primaryCategory:"cs.CL",published:"2026-10-09T00:00:00Z"},{id:"2610.09633",title:"Coding-Agent Benchmarks Should Match Their Users' Task Flows",up:11,href:"https://arxiv.org/abs/2610.09633",abstract:"The evaluation of coding agents generally strives to be as realistic as possible. In our study, we collect 4,782 agent sessions of real software engineers in JetBrains IDEs, which we call Production Sessions. Since our subject is interactive agents, we study the sessions with at least three user messages (33% of the sample). These long sessions differ from issue-derived benchmark tasks in two ways: (i) user requests span a far wider mix of task types - questions about the project's code, planning, review, refactoring, execution - and (ii) users switch between types throughout a session. Long-s",pdfUrl:"https://arxiv.org/pdf/2610.09633",primaryCategory:"cs.LG",published:"2026-10-07T00:00:00Z"},{id:"2610.10288",title:"TouchScale: 500 Hours of Human Vision and Touch for Visual-Tactile Learning",up:11,href:"https://arxiv.org/abs/2610.10288",abstract:"Large-scale egocentric human interaction data is becoming an important source of physical supervision for embodied learning, yet video alone leaves the contact and pressure that characterize physical interaction unrecorded. Recent visual-tactile datasets provide this missing supervision, but their synchronized tactile data remain far smaller in volume than human video. Moreover, the largest resources often merge recordings from different sensors or annotation procedures, which makes the effect of data scale difficult to isolate. We therefore introduce TouchScale, a 500-hour dataset of contact-",pdfUrl:"https://arxiv.org/pdf/2610.10288",primaryCategory:"cs.CV",published:"2026-10-07T00:00:00Z"},{id:"2610.13171",title:"PreSTO: Predictive Subtree Prefetching for Fast LLM Power Sampling",up:11,href:"https://arxiv.org/abs/2610.13171",abstract:"Power sampling improves large language model (LLM) reasoning at test time by sampling from a sharpened version of the base model's distribution. Its sampler, PowerMH, is slow because its Metropolis--Hastings (MH) updates are sequential: each accept/reject decision sets the state from which the next proposal is generated. Prior work reduces this cost by changing the sampler or the model (e.g., sequential Monte Carlo, approximate lookahead, distillation). We propose Predictive SubTree Prefetching (PreSTO), which accelerates PowerMH by prefetching future proposals and provably leaves its MH trans",pdfUrl:"https://arxiv.org/pdf/2610.13171",primaryCategory:"cs.CL",published:"2026-10-09T00:00:00Z"},{id:"2610.00898",title:"When Do Biological Reasoning Models Use Their Biological Inputs?",up:10,href:"https://arxiv.org/abs/2610.00898",abstract:"Biological reasoning models use post-training to connect LLMs to biological foundation model representations and biological text. Their benchmark accuracy is taken as evidence that LLMs reason over these inputs. We test this assumption in six biological reasoning models across DNA, protein, and single-cell tasks. We perturb one biological input while holding the query and other inputs fixed, construct evidence conflicts that pair the foundation model representation of one genome, protein, or cell with the text of another, fit linear probes to the representations the language model receives, an",pdfUrl:"https://arxiv.org/pdf/2610.00898",primaryCategory:"cs.LG",published:"2026-10-01T00:00:00Z"},{id:"2610.12114",title:"Universal Textual Teaching for LLMs",up:10,href:"https://arxiv.org/abs/2610.12114",abstract:"Knowledge distillation (KD) transfers knowledge from stronger Teacher models to weaker Student models, but most methods require training the Student parameters, thereby binding the distilled knowledge to a specific architecture and checkpoint. This implicit representation is difficult to interpret or reuse across models and limits KD for API-only or costly-to-train models. This paper studies knowledge transfer for large language models (LLMs). We introduce Universal Textual Teaching (UTT), a parameter-update-free framework that distills observed Teacher-Student knowledge gaps into a textual, i",pdfUrl:"https://arxiv.org/pdf/2610.12114",primaryCategory:"cs.AI",published:"2026-10-08T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);